import{_ as o,l as c,o as e,c as i,v as r,p as n,x as t,d as l,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"GPU 存储层次","description":"","frontmatter":{"title":"GPU 存储层次","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-memory-hierarchy.md","filePath":"cs/gpu-memory-hierarchy.md","lastUpdated":1789023840000}'),d={name:"cs/gpu-memory-hierarchy.md"};function A(m,a,E,_,u,P){const s=c("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="gpu-存储层次" tabindex="-1">GPU 存储层次 <a class="header-anchor" href="#gpu-存储层次" aria-label="Permalink to &quot;GPU 存储层次&quot;">​</a></h1><div class="epigraph"><p>寄存器、共享存储、L1/L2、HBM 的容量与延迟差几个数量级；SIMT 用占用率换延迟隐藏，但带宽仍要程序把访问打到对的那一层。</p><footer>—— 据 NVIDIA CUDA 编程指南中的硬件模型；Lindholm et al., IEEE Micro 2008；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/gpu-simt">上一课</a> 用切 warp 藏延迟，没说数据住哪。CPU 的 <a href="/cs/locality-principle">局部性</a> 与 <a href="/cs/mesi-protocol">MESI</a> 不能原样搬来：GPU 的「共享存储」是程序员可见的暂存，一致性模型更弱。本课不重讲 warp 调度。缺口是<strong>层次：寄存器堆、scratchpad、cache、设备内存，以及它们如何限制占用率。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HBM 带宽高、延迟仍几十到上百 ns。若每个线程每次运算都打 HBM，切 warp 也不够。缺口不是再加 CPU 式的 8 路 L1，而是<strong>把热数据放进每 SM 的共享存储或寄存器，cache 当作自动的那一层，并承认寄存器文件大小直接限制驻留 warp 数。</strong></p><p><span class="marginnote">共享存储（scratchpad）按 bank 组织，冲突会串行化——下一课合并与本课 bank 是带宽的两面。L2 常片上共享，跨 SM 的原子在这里汇合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器把私有变量放寄存器；程序员或编译器把协作缓冲放 shared；其余走全局内存，硬件 cache 可选。占用率：每个 warp 的寄存器数 × warp 数 ≤ 物理堆；shared 用量同样设上限。原子与栅栏在 SM 内走共享存储或 L1；跨 SM 走 L2。</p>',8)),(e(),n(h,null,{default:t(()=>[p(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%AF%8F%E7%BA%BF%E7%A8%8B%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20SM%5B%22%E5%8D%A0%E7%94%A8%E7%8E%87%E4%B8%8A%E9%99%90%22%5D%0A%20%20SHM%5B%22%E5%85%B1%E4%BA%AB%E5%AD%98%E5%82%A8%20scratchpad%22%5D%20--%3E%20SM%0A%20%20L1%5B%22L1%20%2F%20%E7%BA%B9%E7%90%86%22%5D%20--%3E%20L2%5B%22%E7%89%87%E4%B8%8A%20L2%22%5D%0A%20%20L2%20--%3E%20HBM%5B%22%E8%AE%BE%E5%A4%87%E5%86%85%E5%AD%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 CPU：<a href="/cs/vipt-cache">VIPT</a> 仍可能出现在 I-cache/D-cache，但 GPU 更强调带宽而非单线程命中延迟。一致性：许多 GPU 对全局内存提供较弱保证，需要显式栅栏与内存空间限定——对应 CPU 的 <a href="/cs/fence-cost">fence</a>，但粒度是 warp/block。不要把这里写成训练用的 HBM 容量规划；本课只给硬件层次。</p><p>占用率与延迟隐藏是一对：驻留 warp 太少，一次 shared miss 就露馅；寄存器分配过狠则驻留掉下去。编译器报告的 occupancy 是这一层的可读接口，不是 ISA。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每代芯片的 KiB 数当考试。分支发散下一课会让部分 lane 关掉，有效带宽再打折。合并访存再下一课：全局 load 如何合成少量事务。</p><p>后课默认：寄存器与 shared 决定能藏多少延迟。控制流不一致会让一部分 lane 空转。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GPU 层次是寄存器 / scratchpad / cache / HBM；占用率绑在前两层。</li><li>切 warp 藏延迟，带宽仍靠数据放对层。</li><li>分支让共享 PC 破裂，下一课发散。</li><li>出处：Lindholm et al.；CUDA 硬件模型；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const S=o(d,[["render",A]]);export{f as __pageData,S as default};
